export function makeCustom(values,id){const actions={help:['help me with this','helping me with this','你能帮我处理一下这件事吗？'],explain:['explain this question','explaining this question','你能解释一下这个问题吗？'],check:['check this information','checking this information','你能核对一下这个信息吗？']};const a=actions[values.action];return {id,name:values.name,topic:values.goal,icon:'square.and.pencil',goal:values.goal,role:values.role,action:a[0],mind:a[1],meaning:a[2],custom:true,words:[[a[0].split(' ')[0],`放在句子里用：${a[0]}`]],listen:`Could you ${a[0]}?`,listenQuestion:'这句话在做什么？',listenOptions:['请求帮助','描述昨天的事','表示拒绝'],listenAnswer:0,read:`Could you ${a[0]}?`,reply:'Sure. I can help you with that.',replyMeaning:'可以，我能帮你处理。',transfer:{scene:'机场',goal:'请工作人员带你找到登机口。',action:'show me the gate',mind:'showing me the gate',meaning:'你能带我找到登机口吗？'}};}
